#include <vector>
#include <algorithm>

class Solution {
public:
    int getMaxLen(std::vector<int>& nums) {
        int pos = 0, neg = 0, ans = 0;
        for (int x : nums) {
            if (x > 0) {
                pos++;
                neg = (neg > 0 ? neg + 1 : 0);
            } else if (x < 0) {
                int newPos = (neg > 0 ? neg + 1 : 0);
                int newNeg = pos + 1;
                pos = newPos; neg = newNeg;
            } else {
                pos = 0; neg = 0;
            }
            ans = std::max(ans, pos);
        }
        return ans;
    }
};

